// GENERATED by scripts/gen.py settings from settings.toml -- do not edit.
export const SETTINGS = {
  API_BASE: { type: "str", default: "" },
  REQUEST_TIMEOUT_MS: { type: "int", default: "8000" },
} as const;

export type SettingName = keyof typeof SETTINGS;

export function settingText(name: SettingName): string {
  const env = import.meta.env as Record<string, string | undefined>;
  const raw = env[`VITE_${name}`];
  return raw === undefined ? SETTINGS[name].default : raw;
}

export function settingInt(name: SettingName): number {
  const value = Number.parseInt(settingText(name), 10);
  if (Number.isNaN(value)) throw new Error(`setting ${name} is not an integer`);
  return value;
}
